   const plan={macroprocess_ids:p.macroprocess_ids??a.macroprocess_ids,process_ids:p.process_ids??a.process_ids,macroprocesses:p.macroprocesses??a.macroprocesses,processes:p.processes??a.processes,norms:form.getAll('norms'),...readSelections(form),periods,date:periods[0].date,scope:a.audit_type==='F'?form.get('scope'):undefined,manager_name:form.get('manager_name'),location:form.get('location'),manager_email:form.get('manager_email'),confirmed:false};
   validateSelections(plan,data);const body={...a,plan,status:'Plano em rascunho'};validateAudit(body);await api('audits/'+a.id,'PUT',body);selected={id:a.id,tab:'plan'};
