function findingForm(a,existing=null){if(!canManage(a)){toast('Você não é o líder desta auditoria.');return;}
 if(!canEditReport(a)){toast('Somente administradores podem alterar um relatório concluído.');return;}const drafts=existing?{[existing.kind]:existing}:{};let currentKind=existing?.kind||'Conformidade';
 modal(existing?'Editar constatação':'Constatação',select('kind','Classificação',NuclaudReporting.kinds.map(s=>[s,s]),currentKind)+'<div class="wide" id="finding-details"></div>',async form=>{const body={audit_id:a.id,kind:form.get('kind'),description:form.get('description'),requirement_ids:form.getAll('requirement_ids').map(Number),evidence:form.get('evidence'),pac:form.get('pac')};const normalized=NuclaudReporting.validateFinding(body,a,data.requirements);await api(existing?'findings/'+existing.id:'findings',existing?'PUT':'POST',normalized);toast(existing?'Constatação atualizada.':'Constatação salva.');});
 const draw=kind=>{const d=drafts[kind]||{},labels=NuclaudReporting.labels[kind];const detailed=['Conformidade','Não conformidade'].includes(kind);const available=data.requirements.filter(r=>a.plan.requirement_ids?.length?a.plan.requirement_ids.includes(r.id):a.plan.norms.includes(r.norm)).sort((a,b)=>a.norm.localeCompare(b.norm)||a.code.localeCompare(b.code,undefined,{numeric:true}));
  $('#finding-details').innerHTML=(detailed?multiField('requirement_ids','Requisitos relacionados',available.map(r=>[r.id,`${r.norm} · ${r.code}${r.title?' — '+r.title:''}`]),d.requirement_ids||[]):'')+(kind!=='Conformidade'?field('description',labels.description,d.description||'','textarea',true,true):'')+(detailed?field('evidence',labels.evidence,d.evidence||'','textarea',true,true):'')+(kind==='Não conformidade'?field('pac','Número do PAC',d.pac||'','text',true,true):'');initMultiFields();
 };
 $('#fields [name=kind]').onchange=e=>{const old=new FormData($('#form'));drafts[currentKind]={description:old.get('description'),evidence:old.get('evidence'),pac:old.get('pac'),requirement_ids:old.getAll('requirement_ids').map(Number)};currentKind=e.target.value;draw(currentKind);};draw(currentKind);
}

function planText(a){const p=a.plan;return ['PLANO DE AUDITORIA — NUCLAUD',a.code,...supplierRows(a).map(([label,value])=>label+': '+(value||'—')),...internalRows(a,p).map(([label,value])=>label+': '+(value||'—')),'Dias e horários:',periodSummary(p),'Auditor líder: '+p.lead,'Requisitos:',p.requirements].join('\n');}
