function printDocument(a,type){const root=$('#print-document');root.innerHTML=NuclaudReporting.renderDocument(a,data.findings,type,new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}));document.body.classList.add('printing-document');window.addEventListener('afterprint',()=>document.body.classList.remove('printing-document'),{once:true});try{NuclaudEmail.download(a,data.findings,type);}catch(error){document.body.classList.remove('printing-document');toast('Não foi possível gerar o PDF. '+error.message);}}

function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000);}
function validateProcessCatalog(kind,body,state){const name=String(body.name||'').trim();if(!name||name.length>150)throw Error('Informe um nome de até 150 caracteres.');if(kind==='macroprocesses'){if(state.macroprocesses.some(m=>m.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Macroprocesso já cadastrado.');return {name};}const macroprocess_id=+body.macroprocess_id;if(!state.macroprocesses.some(m=>m.id===macroprocess_id))throw Error('Selecione um macroprocesso cadastrado.');if(state.processes.some(p=>p.macroprocess_id===macroprocess_id&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('Processo já cadastrado neste macroprocesso.');const ns=body.norms;if(!Array.isArray(ns)||!ns.length||new Set(ns).size!==ns.length||ns.some(n=>!norms.includes(n)))throw Error('Selecione uma ou mais normas para o processo.');const ids=body.mandatory_requirement_ids||[];if(!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.some(id=>!state.requirements.some(r=>r.id===id&&ns.includes(r.norm))))throw Error('Selecione requisitos obrigatórios das normas do processo.');return {name,macroprocess_id,norms:ns,mandatory_requirement_ids:ids};}
function validateProcessSelection(a,state){if(a.audit_type==='F'){normalizeSupplier(a);return;}if(!a.macroprocess_ids?.length||!a.process_ids?.length)throw Error('Selecione pelo menos um macroprocesso e um processo.');if(new Set(a.macroprocess_ids).size!==a.macroprocess_ids.length||new Set(a.process_ids).size!==a.process_ids.length)throw Error('Seleções de processos duplicadas.');if(a.macroprocess_ids.some(id=>!state.macroprocesses.some(m=>m.id===id))||a.process_ids.some(id=>!state.processes.some(p=>p.id===id&&a.macroprocess_ids.includes(p.macroprocess_id))))throw Error('Selecione processos vinculados aos macroprocessos escolhidos.');if(a.process_ids.some(id=>{const p=state.processes.find(p=>p.id===id);return p?.norms?.length&&!p.norms.some(n=>a.norms.includes(n));}))throw Error('Selecione processos aplicáveis às normas da auditoria.');const mandatory=state.processes.filter(p=>a.process_ids.includes(p.id)).flatMap(p=>p.mandatory_requirement_ids||[]).filter(id=>state.requirements.some(r=>r.id===id&&a.norms.includes(r.norm)));if(mandatory.some(id=>!a.requirement_ids.includes(id)))throw Error('Inclua os requisitos obrigatórios dos processos selecionados.');if(a.macroprocess_ids.some(id=>!a.process_ids.some(pid=>state.processes.some(p=>p.id===pid&&p.macroprocess_id===id))))throw Error('Selecione pelo menos um processo para cada macroprocesso.');}
function processNormChecks(values=[],required=[]){return `<fieldset class="qualification-row"><legend>Normas e requisitos aplicáveis ao processo</legend>${norms.map(n=>`<div class="process-norm-group"><label><input type="checkbox" name="norms" value="${esc(n)}" ${values.includes(n)?'checked':''}>${esc(n)}</label><div class="process-required" data-process-norm="${esc(n)}" ${values.includes(n)?'':'hidden'}><details><summary>Selecionar requisitos aplicáveis ao processo</summary><div class="requirement-options">${orderedRequirements(data.requirements.filter(r=>r.norm===n)).map(r=>`<label><input type="checkbox" name="mandatory_requirement_ids" value="${r.id}" ${required.includes(r.id)?'checked':''}>${esc(r.code)} — ${esc(r.title)}</label>`).join('')||'<p>Cadastre os requisitos desta norma para selecioná-los.</p>'}</div><button type="button" class="text-button" data-close-requirements>Concluir seleção</button></details></div></div>`).join('')}</fieldset>`;}
function bindProcessNorms(root){const update=()=>root.querySelectorAll('[data-process-norm]').forEach(group=>{const selected=[...root.querySelectorAll('[name=norms]:checked')].some(n=>n.value===group.dataset.processNorm);group.hidden=!selected;group.querySelectorAll('input').forEach(i=>i.disabled=!selected);});root.querySelectorAll('[name=norms]').forEach(n=>n.addEventListener('change',update));root.querySelectorAll('[data-close-requirements]').forEach(b=>b.onclick=()=>b.closest('details').open=false);update();}

function processesView(){return `<div class="panel"><div class="panel-head"><h2>Cadastrar macroprocesso</h2></div><form id="macro-register" class="inline-register">${field('name','Nome do macroprocesso','','text',true,true)}<button type="submit" class="primary">Salvar macroprocesso</button><p class="form-message" role="status"></p></form></div><div class="panel"><div class="panel-head"><h2>Cadastrar processo</h2></div><form id="process-register" class="inline-register">${select('macroprocess_id','Macroprocesso',[['','Selecione um macroprocesso'],...(data.macroprocesses||[]).map(m=>[m.id,m.name])],'')}${field('name','Nome do processo','','text',true,true)}${processNormChecks()}<button type="submit" class="primary">Salvar processo</button><p class="form-message" role="status"></p></form></div><div class="panel"><div class="panel-head"><h2>Vínculos cadastrados</h2></div>${(data.macroprocesses||[]).map(m=>`<div class="catalog-row"><strong>${esc(m.name)}</strong><button class="text-button" data-edit-macro="${m.id}">Editar macroprocesso</button><button class="text-button danger" data-delete-catalog="macroprocesses/${m.id}">Excluir macroprocesso</button><p>${data.processes.filter(p=>p.macroprocess_id===m.id).map(p=>`<div class="process-entry"><strong>${esc(p.name)}</strong> <button class="text-button" data-edit-process="${p.id}">Editar processo</button><button class="text-button danger" data-delete-catalog="processes/${p.id}">Excluir processo</button><button class="text-button" data-process-history="${p.id}">Histórico</button><p>${(p.norms||[]).map(tag).join('')||'Normas ainda não definidas'}</p></div>`).join('')||'Nenhum processo vinculado.'}</p></div>`).join('')||empty('Nenhum macroprocesso cadastrado','Cadastre o macroprocesso e depois seus processos.')}</div>`;}
function processForm(p){if(!isAdmin())return;modal('Editar processo',select('macroprocess_id','Macroprocesso',data.macroprocesses.map(m=>[m.id,m.name]),p.macroprocess_id)+field('name','Nome do processo',p.name,'text',true,true)+`<div class="wide">${processNormChecks(p.norms||[],p.mandatory_requirement_ids||[])}</div>`,async form=>{await api('processes/'+p.id,'PUT',{name:form.get('name'),macroprocess_id:+form.get('macroprocess_id'),norms:form.getAll('norms'),mandatory_requirement_ids:form.getAll('mandatory_requirement_ids').map(Number)});},'Salvar processo');bindProcessNorms($('#fields'));}
function processHistory(p){if(!isAdmin())return;const describe=v=>v?`${v.name} · ${data.macroprocesses.find(m=>m.id===v.macroprocess_id)?.name||''} · ${(v.norms||[]).join(', ')}`:'—';modal('Histórico do processo',`<div class="wide"><h3>${esc(p.name)}</h3>${(p.history||[]).map(h=>`<div class="catalog-row"><strong>${esc(h.action)} · ${esc(new Date(h.at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))}</strong><p>Responsável: ${esc(h.by)}<br>Antes: ${esc(describe(h.before))}<br>Depois: ${esc(describe(h.after))}</p></div>`).join('')||'<p>Cadastro anterior ao registro de histórico.</p>'}</div>`,async()=>{},'Fechar');}
function bindProcessRegister(id,path){const form=$('#'+id);form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button'),message=form.querySelector('.form-message');button.disabled=true;try{const fields=new FormData(form);const body=Object.fromEntries(fields);if(path==='processes'){body.norms=fields.getAll('norms');body.mandatory_requirement_ids=fields.getAll('mandatory_requirement_ids').map(Number);}await api(path,'POST',body);await load();$('#'+id+' .form-message').textContent='Cadastro salvo com sucesso.';}catch(error){message.textContent=error.message;message.classList.add('form-error');}finally{button.disabled=false;}};}
function bindProcessChoices(a){const update=()=>{const root=$('#process-choices');const selected=root.querySelector('[name=process_ids]')?[...root.querySelectorAll('[name=process_ids]:checked')].map(x=>+x.value):(a.process_ids||[]);const macros=[...document.querySelectorAll('#fields [name=macroprocess_ids]:checked')].map(x=>+x.value);const ns=[...document.querySelectorAll('#fields [name=norms]:checked')].map(x=>x.value);const options=(data.processes||[]).filter(p=>macros.includes(p.macroprocess_id)&&(!p.norms?.length||p.norms.some(n=>ns.includes(n))));root.innerHTML=multiField('process_ids','Processos',options.map(p=>[p.id,`${data.macroprocesses.find(m=>m.id===p.macroprocess_id).name} › ${p.name}`]),selected);initMultiFields();root.querySelectorAll('[name=process_ids]').forEach(i=>i.onchange=()=>$('#registered-selections').refreshSelections?.());$('#registered-selections').refreshSelections?.();};document.querySelectorAll('#fields [name=norms]').forEach(x=>x.addEventListener('change',update));document.querySelectorAll('#fields [name=macroprocess_ids]').forEach(x=>x.onchange=update);update();}
function readProcessSelection(form){const macroprocess_ids=form.getAll('macroprocess_ids').map(Number),process_ids=form.getAll('process_ids').map(Number);return {macroprocess_ids,process_ids,macroprocesses:macroprocess_ids.map(id=>data.macroprocesses.find(m=>m.id===id)?.name).join(' · '),processes:process_ids.map(id=>{const p=data.processes.find(p=>p.id===id);const m=data.macroprocesses.find(m=>m.id===p?.macroprocess_id);return `${m?.name||''} › ${p?.name||''}`;}).join('\n')};}
function validateUser(body,state){
 const user={username:body.username.trim().toLocaleLowerCase(),full_name:body.full_name.trim(),email:body.email.trim(),role:body.role,auditor_id:+body.auditor_id||null};
 if(!/^[\w.@\\-]{2,100}$/.test(user.username)||!user.full_name||!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(user.email))throw Error('Informe nome de rede, nome completo e e-mail válidos.');
 if(!['admin','user'].includes(user.role))throw Error('Perfil inválido.');
 if(state.users.some(u=>u.username.toLocaleLowerCase()===user.username))throw Error('Nome de rede já cadastrado.');
 if(user.role==='user'&&!state.auditors.some(a=>a.id===user.auditor_id&&Object.values(a.qualifications).some(r=>roles(r).includes('leader'))))throw Error('Vincule o usuário a um auditor com habilitação de líder.');
 return user;
}
function usersView(){return `<div class="panel"><div class="panel-head"><h2>Usuários do sistema</h2><button class="primary" id="add-user">＋ Cadastrar usuário</button></div>${lastCredential?`<div class="notice">Usuário criado. Senha temporária (exibida apenas agora): <code>${esc(lastCredential)}</code>. Entregue-a ao usuário por um canal seguro.</div>`:''}<div class="table-wrap"><table><thead><tr><th>Nome de rede</th><th>Nome completo</th><th>E-mail</th><th>Perfil</th><th>Auditor vinculado</th><th>Ações</th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.username)}</td><td>${esc(u.full_name)}</td><td>${esc(u.email)}</td><td>${u.role==='admin'?'Administrador':'Usuário'}</td><td>${esc(data.auditors.find(a=>a.id===u.auditor_id)?.name||'—')}</td><td><button class="text-button" data-edit-user="${u.id}">Editar usuário</button><button class="text-button danger" data-delete-catalog="users/${u.id}">Excluir usuário</button></td></tr>`).join('')}</tbody></table></div></div>`;}
function userForm(u={}){if(!isAdmin())return;modal(u.id?'Editar usuário':'Cadastrar usuário',field('username','Nome de rede',u.username||'','text',false,true)+field('full_name','Nome completo',u.full_name||'','text',false,true)+field('email','E-mail',u.email||'','email',true,true)+select('role','Perfil',[['user','Usuário'],['admin','Administrador']],u.role||'user')+select('auditor_id','Auditor vinculado (obrigatório para Usuário)',[['','Selecione um auditor líder'],...data.auditors.filter(a=>Object.values(a.qualifications).some(r=>roles(r).includes('leader'))).map(a=>[a.id,a.name])],u.auditor_id||'')+`<p class="wide">O vínculo identifica quais auditorias o usuário pode conduzir. ${u.id?'A senha atual é preservada.':previewMode()?'Na prévia, use o seletor Perfil de teste para experimentar os acessos; não há autenticação real.':'Uma senha temporária será gerada ao salvar. O usuário poderá alterá-la após entrar.'}</p>`,async form=>{const body=validateUser(Object.fromEntries(form),{...data,users:data.users.filter(x=>x.id!==u.id)});const result=await api(u.id?'users/'+u.id:'users',u.id?'PUT':'POST',body);lastCredential=result.temporary_password||null;view='users';selected=null;},'Salvar usuário');}
function renderAccess(){
 const admin=isAdmin();$('nav').hidden=!currentUser;document.querySelectorAll('[data-admin-only]').forEach(el=>el.hidden=!admin);
 $('#new-audit').hidden=!admin;$('.toolbar').hidden=!currentUser;
 const header=$('#identity-controls');
 if(previewMode()&&currentUser){header.innerHTML=`<span class="demo-label">Prévia: perfis simulados</span><label>Perfil de teste <select id="demo-profile" aria-label="Perfil de teste">${(data.demo_users||[]).map(u=>`<option value="${u.id}" ${u.id===currentUser.id?'selected':''}>${esc(u.full_name)} — ${u.role==='admin'?'Administrador':'Usuário'}</option>`).join('')}</select></label>`;$('#demo-profile').onchange=async e=>{await api('demo-profile','POST',{user_id:+e.target.value});lastCredential=null;selected=null;view='calendar';await load();};}
 else if(currentUser){header.innerHTML=`<span>${esc(currentUser.full_name)} · ${admin?'Administrador':'Usuário'}</span><button class="text-button" id="change-password">Alterar senha</button><button class="text-button" id="logout">Sair</button>`;$('#logout').onclick=async()=>{await api('logout','POST',{});currentUser=null;data={audits:[],findings:[],areas:[],auditors:[],requirements:[],users:[]};selected=null;await load();};$('#change-password').onclick=()=>modal('Alterar senha',field('current_password','Senha atual','','password',true,true)+field('new_password','Nova senha (mínimo 10 caracteres)','','password',true,true),async form=>{await api('password','POST',Object.fromEntries(form));});}
 else header.textContent='Acesso ao NUCLAUD';
}
function showAuth(setup){renderAccess();$('#page-title').textContent=setup?'Configurar administrador inicial':'Entrar no NUCLAUD';$('#subtitle').textContent='Autenticação local do servidor. O nome de rede identifica a conta; não há integração automática com o diretório da empresa.';$('#app').innerHTML=`<form id="auth-form" class="panel auth-form">${field('username','Nome de rede','','text',true,true)}${setup?field('full_name','Nome completo','','text',true,true)+field('email','E-mail','','email',true,true):''}${field('password','Senha'+(setup?' (mínimo 10 caracteres)':''),'','password',true,true)}${setup?field('setup_token','Chave de instalação (servidor remoto)','','password',true):''}<p id="auth-error" role="alert"></p><button class="primary" type="submit">${setup?'Criar administrador':'Entrar'}</button></form>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api(setup?'setup':'login','POST',Object.fromEntries(new FormData(e.target)));view='calendar';await load();}catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}};}
$('#form').onsubmit=async e=>{e.preventDefault();const b=$('#form button[type=submit]');b.disabled=true;try{await submitAction(new FormData($('#form')));$('#modal').close();await load();toast('Registro salvo com sucesso');}catch(e){$('#error').textContent=e.message;if(e.status===401){$('#modal').close();await load();}}finally{b.disabled=false;}};
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>$('#modal').close());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=null;lastCredential=null;render();});$('#new-audit').onclick=()=>scheduleForm();$('#year').onchange=()=>{selected=null;render();};$('#search').oninput=()=>{selected=null;render();};load();
